      "content": "export function buildProgressChecklist(input) {
  // Validate input is non-null object
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  // Validate title
  const { title, milestones } = input;
  if (typeof title !== 'string' || title.length < 1 || title.length > 128) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  // Validate milestones is array
  if (!Array.isArray(milestones)) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  // Validate milestones array length
  if (milestones.length > 200) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  // Validate each milestone
  const validStates = new Set(['OPEN', 'IN_PROGRESS', 'CLOSED', 'BLOCKED']);
  const seenIds = new Set();
  const rows = [];

  for (let i = 0; i < milestones.length; i++) {
    const m = milestones[i];
    if (m === null || typeof m !== 'object' || Array.isArray(m)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Check exact keys
    const keys = Object.keys(m);
    if (keys.length !== 3 || !keys.includes('id') || !keys.includes('label') || !keys.includes('state')) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    const { id, label, state } = m;

    // Validate id
    if (typeof id !== 'string' || id.length < 1 || id.length > 128) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Validate label
    if (typeof label !== 'string' || label.length < 1 || label.length > 128) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Validate state
    if (!validStates.has(state)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Validate unique id
    if (seenIds.has(id)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }
    seenIds.add(id);

    // Copy milestone
    rows.push({ id, label, state });
  }

  // Calculate summary
  const total = rows.length;
  let closed = 0, open = 0, inProgress = 0, blocked = 0;

  for (let i = 0; i < rows.length; i++) {
    switch (rows[i].state) {
      case 'CLOSED': closed++; break;
      case 'OPEN': open++; break;
      case 'IN_PROGRESS': inProgress++; break;
      case 'BLOCKED': blocked++; break;
    }
  }

  const percent = total === 0 ? null : Math.floor(closed * 100 / total);

  return {
    schemaVersion: 1,
    status: 'READY',
    title,
    rows,
    summary: {
      total,
      closed,
      open,
      inProgress,
      blocked,
      percent
    },
    basis: 'equal-weight milestone count; not effort, accuracy or release readiness',
    authorizing: false
  };
}
"
